    avlInsert(root->left, item);
} else if (item > root->data) {
    avlInsert(root->right, item);
} else {
    return;
}

root->height = 1 + std::max(height(root->left), height(root->right));

int balance = getBalance(root);

if (balance > 1 && item < root->left->data) {
    // Left Left Case
    returnRightRotation(root);
} else if (balance < -1 && item > root->right->data) {
    // Right Right Case
    returnLeftRotation(root);
} else if (balance > 1 && item > root->left->data) {
    // Left Right Case
    root->left = leftRotation(root->left);
    root = rightRotation(root);
} else if (balance < -1 && item < root->right->data) {
    // Right Left Case
    root->right = rightRotation(root->right);
    root = leftRotation(root);
} else {
    return;
}

int lh = height(root->left);
    int rh = height(root->right);
    root->height = 1 + std::max(lh, rh);
    root->height = 1 + std::max(height(root->left), height(root->right));
}
